 internal const string EvidenceFileName="final",EvidenceKind="kind",PendingFileName="pending",PendingKind="pending-kind";
 internal RuntimeRequest request=new RuntimeRequest();internal Selection selection=new Selection();internal RuntimeSaveAuthorization authorization=new RuntimeSaveAuthorization();internal PersistenceSaveAuthorization authority=new PersistenceSaveAuthorization();internal World world=new World();internal Controls controls=new Controls();internal Persistence persistence=new Persistence();internal Game game;internal SaveManager manager;internal Player menuPlayer;internal int generation=1;internal string root=@"C:\Virtual\cold\Saved Games";internal Clock clock=new Clock();internal JObject evidence=new JObject(),sourceWorld=new JObject();internal List<string> errors=new List<string>();internal List<RuntimeSubscenarioResult> results=new List<RuntimeSubscenarioResult>();internal NativeArchiveRestorationProbe restoration;internal Chunk7BootstrapInventoryProbe probe;
 internal object nativePlayer,state,areaState,mainState,area,mainActor;internal Actor[] actors;internal object[] descriptors,views;internal string expectedMainId="actor";internal bool begun,admitted,cleanup,completed,settled,disposed,pending,sourcePinned,ReadFails,VerifyFails;internal double cleanupStart;internal int ReadCount;
 internal Scenario(){Game.Instance=game=new Game();manager=game.SaveManager;menuPlayer=game.Player;manager.SavePath=root;authority.Root=root;authorization.Scope=authority;NativePersistenceIsolation.Authority=authority;NativePersistenceIsolation.ObservedStashFolder=Path.Combine(Path.GetDirectoryName(root),"Areas");}
