internal static class BootstrapInventoryActualTests{
 static int passes,fails;static void Check(bool b,string message){if(!b)throw new Exception(message);}static void Reset(){LoadingProcess.Instance=null;DialogMessageBox.Instance=null;Game.NewGameUnit=null;NativePersistenceIsolation.HasPendingWrites=false;NativeArchiveRestorationProbe.InstallFails=NativeArchiveRestorationProbe.DisposeFails=false;HarmonyInstance.PatchFails=HarmonyInstance.UnpatchFails=false;HarmonyInstance.Patches=HarmonyInstance.Unpatches=0;MetadataBoundary.Fails=false;RuntimeLoaderInventory.ThrowFinal=false;RuntimeLoaderInventory.Leaves.Clear();UnityEngine.Time.frameCount=1;}
 static void Good(string name,Action test){try{Reset();test();passes++;Console.WriteLine("PASS "+name);}catch(Exception e){fails++;Console.WriteLine("FAIL "+name+": "+e.Message);}}
 static void Refused(Action action){bool no=false;try{action();}catch(InvalidOperationException){no=true;}Check(no,"expected refusal");}
 static int Main(){
 Good("pre-load observers owned before a single native load",()=>{var s=new Scenario();s.BeginBeforeLoad();Check(s.probe!=null&&s.restoration!=null&&s.ReadCount==1,"observers absent");Check(s.authorization.AuthorizedLoadCount==0,"load manufactured");Check(s.DrainForHost(),"idle observers retained");});
 foreach(var item in new[]{"admitted","authorized","world","main","new game","load","queued","write","dialog","owner","prepared","cast","slot","snapshot","restore"}){var name=item;Good("preload rejects "+name,()=>{var s=new Scenario();switch(name){case "admitted":s.authority.AdmittedNativeLoadRequests=1;break;case "authorized":s.authorization.AuthorizedLoadCount=1;break;case "world":s.game.CurrentlyLoadedArea=new Asset();break;case "main":s.game.Player.MainCharacter.Value=new Actor();break;case "new game":Game.NewGameUnit=new object();break;case "load":LoadingProcess.Instance=new LoadingProcess{IsLoadingInProcess=true};break;case "queued":LoadingProcess.Instance=new LoadingProcess();LoadingProcess.Instance.QueuedNames.Add("other");break;case "write":NativePersistenceIsolation.HasPendingWrites=true;break;case "dialog":DialogMessageBox.Instance=new DialogMessageBox{IsShown=true};break;case "owner":s.world.Registry.Owners=new[]{new object()};break;case "prepared":s.world.UnifiedTurn.HasUnsettledPreparation=true;break;case "cast":s.controls.NativeCastRequestCount=1;break;case "slot":s.controls.Slots=new[]{new object()};break;case "snapshot":s.persistence.SnapshotCount=1;break;case "restore":s.persistence.SemanticRestoreCount=1;break;}Refused(()=>s.BeginBeforeLoad());Check(s.probe==null&&s.restoration==null,"observer installed after refused admission");});}
 Good("partial source failure leaves no phantom byte pin",()=>{var s=new Scenario{ReadFails=true};try{s.BeginBeforeLoad();}catch{}Check(!s.sourcePinned&&s.probe==null,"invalid source pinned");Check(s.DrainForHost(),"ownless cleanup retained");});
 Good("partial first patch retained and unpatch retryable",()=>{var s=new Scenario();HarmonyInstance.PatchFails=true;try{s.BeginBeforeLoad();}catch{}Check(s.probe!=null&&s.restoration==null,"lost first observer");HarmonyInstance.UnpatchFails=true;Check(!s.DrainForHost(),"failed cleanup completed");HarmonyInstance.UnpatchFails=false;Check(s.DrainForHost(),"retry did not settle");});
 Good("partial second installation keeps both observers",()=>{var s=new Scenario();NativeArchiveRestorationProbe.InstallFails=true;try{s.BeginBeforeLoad();}catch{}Check(s.probe!=null&&s.restoration!=null,"lost second field");NativeArchiveRestorationProbe.DisposeFails=true;Check(!s.DrainForHost(),"first failure completed");Check(s.probe.IdentityReleased,"independent first disposal skipped");NativeArchiveRestorationProbe.DisposeFails=false;Check(s.DrainForHost(),"second retry failed");});
 foreach(var item in new[]{"Game","manager","scope","generation","root","stash","plan","write"}){var name=item;Good("cleanup retains foreign "+name,()=>{var s=new Scenario();s.BeginBeforeLoad();switch(name){case "Game":Game.Instance=new Game();break;case "manager":s.game.SaveManager=new SaveManager();break;case "scope":s.authorization.Scope=new object();break;case "generation":s.authorization.AuthorityGeneration=2;break;case "root":s.manager.SavePath="foreign";break;case "stash":NativePersistenceIsolation.ObservedStashFolder="foreign";break;case "plan":s.authority.Plan=false;break;case "write":s.authorization.AuthorizedWriteCount=1;break;}Check(!s.DrainForHost()&&HarmonyInstance.Unpatches==0,"foreign authority released observers");Game.Instance=s.game;s.game.SaveManager=s.manager;s.authorization.Scope=s.authority;s.authorization.AuthorityGeneration=1;s.manager.SavePath=s.root;NativePersistenceIsolation.ObservedStashFolder=Path.Combine(Path.GetDirectoryName(s.root),"Areas");s.authority.Plan=true;s.authorization.AuthorizedWriteCount=0;Check(s.DrainForHost(),"exact retry failed");});}
 foreach(var item in new[]{"load","queued","write","save","admission","world","area","drain","owner","prepared","command"}){var name=item;Good("cleanup waits "+name,()=>{var s=new Scenario();s.BeginBeforeLoad();switch(name){case "load":LoadingProcess.Instance=new LoadingProcess{IsLoadingInProcess=true};break;case "queued":LoadingProcess.Instance=new LoadingProcess();LoadingProcess.Instance.QueuedNames.Add("load");break;case "write":NativePersistenceIsolation.HasPendingWrites=true;break;case "save":s.persistence.HasActiveSaveScope=true;break;case "admission":s.persistence.HasSaveAdmissionFence=true;break;case "world":s.world.SerializationBusy=true;break;case "area":s.persistence.AreaTransitionPending=true;break;case "drain":s.persistence.Drain=OwnedWorkerTeardownVerdict.Refused;break;case "owner":s.world.Registry.Owners=new[]{new object()};break;case "prepared":s.world.UnifiedTurn.HasUnsettledPreparation=true;break;case "command":s.world.Pairs[0].Combat.HasActiveCommand=true;break;}Check(!s.DrainForHost()&&HarmonyInstance.Unpatches==0,"unsettled callback released");s.clock.Seconds=46;Check(!s.DrainForHost()&&RuntimeLoaderInventory.Leaves.SetEquals(new[]{"pending"}),"pending final collision");LoadingProcess.Instance=null;NativePersistenceIsolation.HasPendingWrites=false;s.persistence.HasActiveSaveScope=s.persistence.HasSaveAdmissionFence=s.persistence.AreaTransitionPending=false;s.persistence.Drain=OwnedWorkerTeardownVerdict.Settled;s.world.SerializationBusy=false;s.world.Registry.Owners=new object[0];s.world.UnifiedTurn.HasUnsettledPreparation=false;s.world.Pairs[0].Combat.HasActiveCommand=false;Check(s.DrainForHost()&&RuntimeLoaderInventory.Leaves.SetEquals(new[]{"pending","final"}),"settlement failed");});}
 foreach(var item in new[]{"Player","state","area state","main state","area","main actor","actor","descriptor","view"}){var name=item;Good("admitted-world cleanup refuses replacement "+name,()=>{var s=new Scenario();s.BeginBeforeLoad();s.Admit();var player=s.game.Player;var state=s.game.State;var areaState=state.LoadedAreaState;var mainState=areaState.MainState;var area=s.game.CurrentlyLoadedArea;var actor=player.MainCharacter.Value;switch(name){case "Player":s.game.Player=new Player();break;case "state":s.game.State=new State();break;case "area state":state.LoadedAreaState=new AreaState();break;case "main state":areaState.MainState=new object();break;case "area":s.game.CurrentlyLoadedArea=new Asset();break;case "main actor":player.MainCharacter.Value=new Actor();break;case "actor":player.Party[0]=new Actor();break;case "descriptor":actor.Descriptor=new object();break;case "view":actor.View=new object();break;}Check(!s.DrainForHost()&&HarmonyInstance.Unpatches==0,"substituted native world released");s.game.Player=player;s.game.State=state;state.LoadedAreaState=areaState;areaState.MainState=mainState;s.game.CurrentlyLoadedArea=area;player.MainCharacter.Value=actor;player.Party[0]=actor;actor.Descriptor=s.descriptors[0];actor.View=s.views[0];Check(s.DrainForHost(),"original world did not settle");});}
 Good("source/effect failure releases observers without refunds and retains FAIL",()=>{var s=new Scenario();s.BeginBeforeLoad();s.VerifyFails=true;s.persistence.SnapshotCount=1;Check(s.DrainForHost(),"observer-only cleanup blocked on observation error");Check(s.errors.Count>=3&&s.persistence.SnapshotCount==1,"error lost or resource rewritten");});
 Good("artifact write failure does not complete",()=>{var s=new Scenario();s.BeginBeforeLoad();RuntimeLoaderInventory.ThrowFinal=true;Check(!s.DrainForHost()&&!s.completed,"writer failure marked complete");RuntimeLoaderInventory.ThrowFinal=false;Check(s.DrainForHost(),"final retry failed");});
 Good("actual PostLoad exact owner and synchronous return",()=>{var g=new Game();Game.Instance=g;var p=new Chunk7BootstrapInventoryProbe(g);p.Install();Check(!p.Complete,"unobserved probe complete");Invoke(p,g.Player,true);Check(p.InSynchronousCallback,"callback not retained");Refused(()=>p.Dispose());Invoke(p,g.Player,false);Check(p.Complete,"exact callback failed");p.Dispose();Check(p.IdentityReleased,"labels retained");});
 foreach(var item in new[]{"Game","manager","Player","second entry","late exit"}){var name=item;Good("actual PostLoad rejects "+name,()=>{var g=new Game();Game.Instance=g;var p=new Chunk7BootstrapInventoryProbe(g);p.Install();Invoke(p,g.Player,true);switch(name){case "Game":Game.Instance=new Game();break;case "manager":g.SaveManager=new SaveManager();break;case "Player":g.Player=new Player();break;case "second entry":Invoke(p,g.Player,true);break;case "late exit":UnityEngine.Time.frameCount++;break;}Invoke(p,g.Player,false);Check(!p.Complete,"invalid callback became complete");p.Dispose();});}
 Console.WriteLine("TOTAL PASS="+passes+" FAIL="+fails);return fails==0?0:1;
 }
 static void Invoke(Chunk7BootstrapInventoryProbe p,Player player,bool before)=>typeof(Chunk7BootstrapInventoryProbe).GetMethod("Observe",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(p,new object[]{player,before});
